139: // onRCRulesUpdate is the RC callback called when security rules related RC updates are available
140: func (a *appsec) onRCRulesUpdate(updates map[string]remoteconfig.ProductUpdate) map[string]rc.ApplyStatus {
141: 	// If appsec was deactivated through RC, stop here
142: 	if !a.started {
143: 		return map[string]rc.ApplyStatus{}
144: 	}
145: 
146: 	// Create a new local rulesManager
147: 	r := a.cfg.rulesManager.clone()
148: 	statuses, err := combineRCRulesUpdates(r, updates)
149: 	if err != nil {
150: 		log.Debug("appsec: Remote config: not applying any updates because of error: %v", err)
151: 		return statuses
152: 	}
153: 
154: 	// Compile the final rules once all updates have been processed and no error occurred
155: 	r.compile()
156: 	log.Debug("appsec: Remote config: final compiled rules: %s", r)
157: 
158: 	// If an error occurs while updating the WAF handle, don't swap the rulesManager and propagate the error
159: 	// to all config statuses since we can't know which config is the faulty one
160: 	if err = a.swapWAF(r.latest); err != nil {
161: 		log.Error("appsec: Remote config: could not apply the new security rules: %v", err)
162: 		for k := range statuses {
163: 			statuses[k] = genApplyStatus(true, err)
164: 		}
165: 		return statuses
166: 	}
167: 	// Replace the rulesManager with the new one holding the new state
168: 	a.cfg.rulesManager = r
169: 
170: 	return statuses
171: }
